FONT_DATA_B64 = (

    # ===============================
    # 从这里开始粘贴字体转换后的编码
    # ===============================

    # ===============================
    # 到这里结束def 
    # ===============================

)

def register_chinese_font(font_dir):
    """
    解压内嵌中文字体，并注册为 Kivy 默认字体。
    """

    if not FONT_DATA_B64.strip():
        raise RuntimeError(
            "尚未添加中文字体编码，请将字体代码粘贴到 FONT_DATA_B64 区域。"
        )

    font_path = os.path.join(
        font_dir,
        "NotoSansSC-Regular.otf"
    )

    os.makedirs(font_dir, exist_ok=True)

    # 如果字体文件不存在或为空，则自动解压
    if not os.path.isfile(font_path) or os.path.getsize(font_path) == 0:

        try:
            # Base64 解码
            compressed = base64.b64decode(
                FONT_DATA_B64.encode("ascii"),
                validate=True
            )

            # GZIP 解压
            font_bytes = gzip.decompress(compressed)

            if not font_bytes:
                raise ValueError("解压后的字体文件为空")

            # 检查字体文件格式
            if font_bytes[:4] not in (
                b"OTTO",
                b"\x00\x01\x00\x00"
            ):
                raise ValueError("字体文件格式不正确")

            # 先写入临时文件，成功后再替换
            temp_path = font_path + ".tmp"

            with open(temp_path, "wb") as f:
                f.write(font_bytes)

            os.replace(temp_path, font_path)

        except Exception as e:
            raise RuntimeError(
                f"中文字体解压失败：{e}"
            )

    # 注册为 Kivy 默认字体
    LabelBase.register(
        name="Roboto",
        fn_regular=font_path,
        fn_bold=font_path,
        fn_italic=font_path,
        fn_bolditalic=font_path
    )

    # 同时注册一个独立字体名称
    LabelBase.register(
        name="Chinese",
        fn_regular=font_path,
        fn_bold=font_path,
        fn_italic=font_path,
        fn_bolditalic=font_path
    )

    print("中文字体注册成功：", font_path)


