class GarmentLedgerApp(App):
    title = APP_NAME

    def build(self):

        # ====================================================
        # 第一步：注册中文字体
        # 必须放在创建界面控件之前
        # ====================================================
        register_chinese_font(self.user_data_dir)

        # ====================================================
        # 第二步：初始化原有数据库
        # ====================================================
        self.db = DB(
            os.path.join(
                self.user_data_dir,
                "garment_ledger.sqlite3"
            )
        )

        # ====================================================
        # 第三步：加载原有 Kivy 界面
        # ====================================================
        Builder.load_string(KV)

        # 下面继续保留你原来的 build() 代码
        sm = ScreenManager()
        sm.add_widget(MainScreen(name="main"))
        sm.add_widget(EditScreen(name="edit"))
        sm.add_widget(DetailScreen(name="detail"))
        sm.add_widget(WageScreen(name="wage"))
        sm.add_widget(SettingsScreen(name="settings"))
        # 首页底部导航通过顶栏快捷按钮提供，避免遮挡小屏幕内容
        shell = BoxLayout(orientation="vertical")
        nav = GridLayout(cols=3, size_hint_y=None, height=dp(48), spacing=dp(3))
        for label, target in [("记工首页","main"),("工资管理","wage"),("设置","settings")]:
            nav.add_widget(Button(text=label, on_release=lambda _, t=target: setattr(sm, "current", t)))
        shell.add_widget(nav)
        shell.add_widget(sm)
        return shell

    def on_stop(self):
        if hasattr(self, "db"):
            self.db.conn.commit()
            self.db.conn.close()

if __name__ == "__main__":
    GarmentLedgerApp().run()
    
